-- 컨디션 노드(node 타입) 사용 요건을 더 분명하게 — 생성 단계에서 무의미한 컨디션 노드가 아예 안 만들어지도록.
-- 기존 "컨디션 노드는 시나리오 시작·분기 전용"(order 60)을 요건·금지·대안을 명시한 강한 버전으로 갱신하고
-- 다른 컨디션 규칙(order 5/10)과 인접하도록 order_index를 12로 올린다(프롬프트 상단에 더 잘 노출).

UPDATE solution_rules SET
  order_index = 12,
  description =
    '컨디션 노드(node 타입)는 (1) 시나리오 진입 트리거이거나 (2) 분기(갈래 나눔)의 시작점일 때만 만든다. 컨디션 노드를 새로 두기 전에 아래 둘 중 하나를 반드시 만족하는지 확인하고, 둘 다 아니면 만들지 마라. (1) 시나리오 진입: 그 시나리오의 첫 기능 노드이자 루트(greeting·다른 시나리오와 형제)로, 진입 발화로 트리거된다. (2) 분기: 흐름이 서로 배타적인 둘 이상의 갈래로 나뉘는 지점이며, 갈래는 자식 노드들의 condition으로 판별한다(자식이 둘 이상). 다음은 금지: 분기 없이 다음 한 노드로만 이어지는 컨디션 노드, 흐름/루프 본문 끝의 잎(자식 없는) 컨디션 노드, ''확인''·''판단''·''처리''·''시작'' 같은 라벨만 달고 실제 갈래도 동작도 없는 컨디션 노드. 분기가 아니라 단순히 다음 단계로 넘어가는 자리에는 컨디션 노드를 두지 말고 그 동작 노드(output·set·api·esd)를 직접 잇거나, 마땅한 동작이 없으면 노드 자체를 만들지 마라. 예: 반복 수집에서 ''더 받을지''는 단독 컨디션 노드가 아니라 요청 output의 자식 둘로 갈라(종료 발화면 set으로 exitVar=true / 아니면 누적 set) 처리한다.',
  updated_at = now()
WHERE category='Node Usage Rule' AND title='컨디션 노드는 시나리오 시작·분기 전용';

-- 행이 없을 때만(신규 환경) 삽입 — 위 UPDATE가 적용된 환경에서는 NOT EXISTS로 건너뜀.
INSERT INTO solution_rules (category, title, description, content, order_index)
SELECT 'Node Usage Rule', '컨디션 노드는 시나리오 시작·분기 전용',
  '컨디션 노드(node 타입)는 (1) 시나리오 진입 트리거이거나 (2) 분기(갈래 나눔)의 시작점일 때만 만든다. 컨디션 노드를 새로 두기 전에 아래 둘 중 하나를 반드시 만족하는지 확인하고, 둘 다 아니면 만들지 마라. (1) 시나리오 진입: 그 시나리오의 첫 기능 노드이자 루트(greeting·다른 시나리오와 형제)로, 진입 발화로 트리거된다. (2) 분기: 흐름이 서로 배타적인 둘 이상의 갈래로 나뉘는 지점이며, 갈래는 자식 노드들의 condition으로 판별한다(자식이 둘 이상). 다음은 금지: 분기 없이 다음 한 노드로만 이어지는 컨디션 노드, 흐름/루프 본문 끝의 잎(자식 없는) 컨디션 노드, ''확인''·''판단''·''처리''·''시작'' 같은 라벨만 달고 실제 갈래도 동작도 없는 컨디션 노드. 분기가 아니라 단순히 다음 단계로 넘어가는 자리에는 컨디션 노드를 두지 말고 그 동작 노드(output·set·api·esd)를 직접 잇거나, 마땅한 동작이 없으면 노드 자체를 만들지 마라. 예: 반복 수집에서 ''더 받을지''는 단독 컨디션 노드가 아니라 요청 output의 자식 둘로 갈라(종료 발화면 set으로 exitVar=true / 아니면 누적 set) 처리한다.',
  '{}'::jsonb, 12
WHERE NOT EXISTS (SELECT 1 FROM solution_rules WHERE category='Node Usage Rule' AND title='컨디션 노드는 시나리오 시작·분기 전용');
